<?php
 require_once(__DIR__ . '/../init.php'); class pmed_insurance_brocker { const TASK_NAME = 'pmedInsuranceSettings'; const DEBUG_HTTP = true; private $db; public function getBrockerData() { $db = $this->db ?: $this->db = connectDb(); $sql = <<<"EOT"
SELECT
    InsuranceBrockerCode "id",
    Action "action",
    ActionType "actionType",
    Data "data"
FROM InsuranceBrocker
ORDER BY ActionOrder, InsuranceBrockerCode
LIMIT 100
EOT;
$items = selectSql($db, $sql); $total_count = count($items); if ($total_count) { $this->log("Получено $total_count записей, требующих обновления. Начало процесса синхронизации..."); return $items; } else { $this->log("Нет данных для отправки"); return false; } } private function getSettings() { if (!empty($this->extraSettings)) { return $this->extraSettings; } $this->log('Загрузка настроек...'); $settings = readExtraSettings(getSessionValue('config'), self::TASK_NAME); return $this->checkSettings($settings); } private function getProxySettings($settings) { return $settings->proxyUse ? array( 'host' => isEmptyProperty($settings, 'proxyServer', ''), 'port' => isEmptyProperty($settings, 'proxyPort', 0), 'usr' => isEmptyProperty($settings, 'proxyUser', ''), 'pwd' => isEmptyProperty($settings, 'proxyPassword', '') ) : array(); } private function checkSettings($settings) { $settingsValid = true; if (empty($settings)) { $this->log('Не произведена настройка обмена информацией с talon.by', 2); } elseif (isset($settings->active) && $settings->active) { if (empty($settings->url)) { $this->log('Не заполнена настройка Адрес сервера API', 2); $settingsValid = false; } if (empty($settings->clientId)) { $this->log('Не заполнена настройка Идентификатор клиента', 2); $settingsValid = false; } if (empty($settings->clientPassword)) { $this->log('Не заполнена настройка Пароль клиента', 1); } if ($settingsValid) { $settings->task = self::TASK_NAME; $this->log('Настройки загружены успешно'); $this->extraSettings = $settings; $result = $this->extraSettings; } else { throw new Exception('Проверьте правильность заполнения данных для подключения.'); } } else { $this->log('В настройках запрещен обмен данными', 1); throw new Exception('В настройках запрещен обмен данными'); } return $result; } public function setupConnect() { $authorization = $this->getAuthorization(); if (empty($authorization)) { $message = "Не найден файл"; $this->log($message, 2); throw new Exception('Проблема с авторизацией'); } $settings = $this->getSettings(); if (!$params = httpCreateParam($settings)) { $message = "Ошибка инициализация подключюения"; $this->log($message, 1); throw new Exception($message); } $params = new stdClass(); $params->url = $settings->url; $params->proxy = $this->getProxySettings($settings); $params->headers['Authorization'] = "Bearer " . $this->authorization; $params->headers['Content-Type'] = "application/json"; $params->debug = self::DEBUG_HTTP; return $params; } private function getAuthorization() { try { $privateKey = file_get_contents(__DIR__ . '/../../../../crt/insuranceKey.pem'); } catch (Throwable $e) { $this->log('Не удалось получить токен доступа'); } return $privateKey; } private function log($message, $type = 0) { app_log($message, $type, self::TASK_NAME); } public function sendBrockerData($items) { $params = $this->setupConnect(); foreach ($items as $row) { $params->request_method = toLower($row['actionType']); switch ($row['action'][1]) { case "UPDATE": $result = httpPUT($params); break; case "CREATE": $result = httpPOST($params); break; case "DELETE": $result = httpDELETE($params); break; } if ($result) { switch ($result['status'][1]) { case "200": $result = safe_json_decode(stristr($result['body'], '{')); $this->log("Сихронизация завершена"); break; case "400": $result = safe_json_decode(stristr($result['body'], '{')); $this->log("Ошибка: $result->reason, $result->message", 2); break; case "404": $result = safe_json_decode(stristr($result['body'], '{')); $this->log("Ошибка: $result->reason, $result->message", 2); break; default: $this->log("Что-то пошло не так...", 2); break; } return $result->data->processed; } else { $this->log("Ошибка подключения к ЦОД"); return false; } } } public function startExchange() { $items = $this->getBrockerData(); if ($items) { $sended = $this->sendBrockerData($items); if ($sended) { $this->deleteResult($sended); return true; } } } } handleJsonRpc('pmed_insurance_brocker'); 